cat > ./test-multi.json << 'EOF'
{
  "subscriptions": [
    { "name": "Meal kit", "price": 5990, "cycle": "weekly", "since": "2026-10-05" },
    { "name": "Netflix", "price": 1299, "cycle": "monthly", "since": "2026-09-27" },
    { "name": "Cloud", "price": 11999, "cycle": "yearly", "since": "2026-01-31" }
  ]
}
EOF
node bin/subtrack.js list --file ./test-multi.json && echo "---" && node bin/subtrack.js renewals --file ./test-multi.json --today 2026-10-24 --within 14

cat > test-export.json << 'EOF'
{
  "subscriptions": [
    { "name": "Meal kit", "price": 5990, "cycle": "weekly", "since": "2026-10-05" }
  ]
}
EOF
node bin/subtrack.js export --file test-export.json --today 2026-10-24 && rm test-export.json
